END;
$$;

-- examples/billing.ts: seatLimit()
--   tier: one of 'enterprise', 'free', 'pro', 'starter' (not enforced here)
CREATE OR REPLACE FUNCTION app.seat_limit(
  tier text,
  extra_seats integer
)
RETURNS integer
LANGUAGE plpgsql
IMMUTABLE
AS $$
BEGIN
  RETURN CASE tier
    WHEN 'free' THEN 1
    WHEN 'starter' THEN 1
    WHEN 'pro' THEN 10 + extra_seats
    ELSE 100 + extra_seats * 2
  END;
END;
$$;

